nodefusion_runtime_overrides.patch:
diff --git a/nodefusion/host/assets/app.css b/nodefusion/host/assets/app.css
index 88f5f82..f2adda9 100644
--- a/nodefusion/host/assets/app.css
+++ b/nodefusion/host/assets/app.css
@@ -415,7 +415,7 @@ tr.sel td { background: color-mix(in oklch, var(--accent) 12%, var(--bg)); }
 .detail-empty-icon { display: grid; place-items: center; width: 32px; height: 32px; border: 1px solid var(--line); border-radius: 6px; color: var(--accent); font-size: 21px; }
 .detail-empty h2 { color: var(--fg); font-size: 14px; margin: 16px 0 5px; }
 .detail-empty p { max-width: 28ch; margin: 0; line-height: 1.55; }
-.trace-controls { display: flex; gap: 8px; margin: 0 0 16px; }
+.trace-controls { display: flex; gap: 8px; margin: 0 0 16px; position: sticky; top: -22px; z-index: 2; background: var(--bg); padding-block: 8px; border-bottom: 1px solid var(--line); }
 .trace-controls input, .trace-controls select { height: 34px; min-width: 150px; padding: 6px 9px; border: 1px solid var(--line); border-radius: 5px; background: var(--bg2); color: var(--fg); }
 .trace-controls input { flex: 1; min-width: 220px; }
 .trace-grid { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 14px; min-height: 420px; }
@@ -460,8 +460,8 @@ tr.sel td { background: color-mix(in oklch, var(--accent) 12%, var(--bg)); }
   .right { width: 100%; max-height: 340px; border-left: 0; border-top: 1px solid var(--line); padding: 14px; }
   .main.detail-collapsed .right { display: none; }
   #evscroll { height: 54vh; }
-  .trace-grid { grid-template-columns: 1fr; }
-  .function-tree, .function-sequence { max-height: 42vh; }
+  .trace-grid { grid-template-columns: 1fr; min-height: 0; align-items: start; }
+  .function-tree, .function-sequence { min-height: 0; max-height: 42vh; }
 }
 @media (max-width: 560px) {
   .brand-kicker, .shortcut-hint { display: none; }

diff --git a/nodefusion/host/assets/app.js b/nodefusion/host/assets/app.js
index 7f1256e..a87dcd9 100644
--- a/nodefusion/host/assets/app.js
+++ b/nodefusion/host/assets/app.js
@@ -28,6 +28,7 @@ const NF = {
   selPage: null,
   selPid: null,
   filters: { text: '', kind: '', res: '', pid: '', cpu: '', group: '', from: '', to: '' },
+  functionFilters: {text: '', cpu: '', limit: '80', grouping: null},
 };

 /* ------------------------------------------------------------------ 工具 */
@@ -1641,6 +1642,10 @@ function renderFunctions() {
   if (returns.nested_entries) grouping.appendChild(new Option('观测调用链', 'stack'));
   if (returns.nested_entries) grouping.value = 'stack';
   else if (!entries.some((e) => e.caller)) grouping.value = 'namespace';
+  search.value = NF.functionFilters.text;
+  cpu.value = NF.functionFilters.cpu;
+  limit.value = NF.functionFilters.limit;
+  if ([...grouping.options].some(option => option.value === NF.functionFilters.grouping)) grouping.value = NF.functionFilters.grouping;
   controls.appendChild(search); controls.appendChild(cpu); controls.appendChild(grouping);
   controls.appendChild(limit); p.appendChild(controls);

@@ -1658,6 +1663,7 @@ function renderFunctions() {
   grid.appendChild(treePanel); grid.appendChild(sequencePanel); p.appendChild(grid);

   function paint() {
+    NF.functionFilters = {text: search.value, cpu: cpu.value, limit: limit.value, grouping: grouping.value};
     const q = search.value.trim().toLowerCase();
     const selectedCpu = cpu.value;
     const filtered = entries.filter((e) => (!q || e.fn.toLowerCase().includes(q) || e.caller.toLowerCase().includes(q) || (e.path || []).some((name) => name.toLowerCase().includes(q))) && (selectedCpu === '' || String(e.cpu) === selectedCpu));
